DELIMITER $$
CREATE TRIGGER `trg_after_insert_request_data` AFTER INSERT ON `request_data` FOR EACH ROW BEGIN
  INSERT INTO request_data_history (
    request_id, status, keterangan, updated_at, updated_by, aksi
  ) VALUES (
    NEW.id,
    NEW.status,
    NEW.keterangan,
    NOW(),
    (SELECT username FROM users WHERE id = NEW.id_user),
    'INSERT'
  );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_after_update_request_data` AFTER UPDATE ON `request_data` FOR EACH ROW BEGIN
  IF (OLD.status IS NULL AND NEW.status IS NOT NULL) OR
     (OLD.status IS NOT NULL AND NEW.status IS NULL) OR
     (OLD.status <> NEW.status) OR
     (OLD.keterangan IS NULL AND NEW.keterangan IS NOT NULL) OR
     (OLD.keterangan IS NOT NULL AND NEW.keterangan IS NULL) OR
     (OLD.keterangan <> NEW.keterangan) THEN

    INSERT INTO request_data_history (
      request_id, status, keterangan, updated_at, updated_by, aksi
    ) VALUES (
      NEW.id,
      NEW.status,
      NEW.keterangan,
      NOW(),
      (SELECT username FROM users WHERE id = NEW.updated_by_id),
      'UPDATE'
    );

  END IF;
END
$$
DELIMITER ;

